INSERT INTO "product_images" (id, "productId", url, alt, "position")
SELECT r.id, p.id, r.url, NULL, r.pos
FROM restore r
JOIN "products" p ON p.sku = r.sku AND p."deletedAt" IS NULL
WHERE NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p.id)
ON CONFLICT (id) DO NOTHING;
